/* ===== Словоход: курсы по возрастам, продолжение (цель Юрия 23.11: у каждого возраста — месяц занятий по каждому предмету) =====
   Предмет с двумя линиями (units + alt) идёт через день, поэтому каждой линии нужно ≥ 10 тем; предмету с одной линией — ≥ 20.
   Тексты и задачи свои, порядок тем — по учебникам 1985–1995 (см. шапку src/cur_ages.js). */

/* ---------- 13 лет: 7 класс ---------- */
M13_ALG.push(
 { id:'a7_11', t:'Среднее, размах, мода, медиана',
   th:UCH({ z:'Пять бросков мячом по кольцу дали очки: 4, 7, 7, 9, 3. Каков средний результат?', pic:'bars|4|7|7|9|3', zr:'(4 + 7 + 7 + 9 + 3) : 5 = 30 : 5 = 6.',
     n:'<b>Среднее арифметическое</b> — сумма чисел, делённая на их количество.<br><b>Размах</b> — разность наибольшего и наименьшего.<br><b>Мода</b> — число, которое встречается чаще всех.<br><b>Медиана</b> — число в середине упорядоченного ряда.',
     x:'Ряд 3, 4, 7, 7, 9: размах 9 − 3 = 6, мода 7, медиана 7.' }),
   g: r => { const n = r.pick([5, 5, 7]); let a; do { a = Array.from({ length: n }, () => r.int(2, 15)); } while (a.reduce((x, y) => x + y, 0) % n); const s = a.slice().sort((x, y) => x - y), sum = a.reduce((x, y) => x + y, 0), avg = sum / n, rng = s[n - 1] - s[0], med = s[(n - 1) / 2];
     const t = r.int(0, 2), L = a.join(', ');
     if (t === 0) return NV(`Найди среднее арифметическое чисел: ${L}.`, avg, [med, rng, avg + 1], `Сумма ${sum}, чисел ${n}: ${sum} : ${n} = ${avg}.`);
     if (t === 1) return NV(`Найди размах ряда: ${L}.`, rng, [s[n - 1], avg, med], `Наибольшее ${s[n - 1]}, наименьшее ${s[0]}: ${s[n - 1]} − ${s[0]} = ${rng}.`);
     return NV(`Найди медиану ряда: ${L}.`, med, [a[(n - 1) / 2], avg, s[(n - 1) / 2 + 1]], `Упорядочим: ${s.join(', ')}. В середине — ${med}.`); } },
 { id:'a7_12', t:'Задачи с помощью систем уравнений',
   th:UCH({ z:'2 тетради и 3 ручки стоят 2 € 60 ц., а 2 тетради и 1 ручка — 1 € 40 ц. Сколько стоит ручка?', zr:'Вычтем из первого второе: 2 ручки стоят 1 € 20 ц., ручка — 60 ц.',
     r:['Обозначаем две неизвестные буквами x и y.', 'Составляем два уравнения по двум условиям.', 'Решаем систему сложением или подстановкой.'],
     x:'x + y = 20, x − y = 4. Сложим: 2x = 24, x = 12, y = 8.' }),
   g: r => { const t = r.int(0, 2);
     if (t === 0) { const x = r.int(8, 30), y = r.int(2, x - 2); return NV(`Сумма двух чисел ${x + y}, а разность ${x - y}. Найди большее число.`, x, [y, x + y - x + 1, (x + y) / 2 | 0], `x + y = ${x + y}, x − y = ${x - y}. Сложим: 2x = ${2 * x}, x = ${x}.`); }
     if (t === 1) { const k = r.int(10, 25), c = r.int(4, 12), K = r.int(3, 9), C0 = r.int(3, 9); return NV(`В зоопарке ${k + c} животных — страусы и козы, у всех вместе ${2 * k + 4 * c} ног. Сколько коз?`, c, [k, c + 2, (2 * k + 4 * c) / 4 | 0], `x + y = ${k + c}, 2x + 4y = ${2 * k + 4 * c}. Если бы все были страусами — ${2 * (k + c)} ног; лишние ${2 * c} ног дают козы по 2: ${c} коз.`); }
     const p = r.int(3, 9) * 10, q = r.int(2, 6) * 10; return NV(`3 булочки и 2 сока стоят ${3 * p + 2 * q} ц., а 1 булочка и 2 сока — ${p + 2 * q} ц. Сколько центов стоит булочка?`, p, [q, p + 10, (3 * p + 2 * q) / 5 | 0], `Вычтем: 2 булочки стоят ${2 * p} ц., одна — ${p} ц.`); } },
 { id:'a7_13', t:'Функции y = x² и y = x³',
   th:UCH({ n:'График <b>y = x²</b> — парабола: симметрична относительно оси y, все значения не меньше нуля.<br>График <b>y = x³</b> — кубическая парабола: при отрицательных x значения отрицательны.',
     x:'(−3)² = 9, а (−3)³ = −27. Точка (2; 4) лежит на параболе y = x², а точка (2; 6) — нет.' }),
   g: r => { const x = r.int(-6, 6) || 3, t = r.int(0, 2);
     if (t === 0) return C(`Найди y = x² при x = ${SG(x)}.`, x * x, [SG(-x * x), 2 * x, x * x + 1].map(String), `${SGp(x)}² = ${x * x}.`);
     if (t === 1) { const z = r.int(-4, 4) || -2; return C(`Найди y = x³ при x = ${SG(z)}.`, SG(z ** 3), [SG(-(z ** 3)), SG(3 * z), SG(z * z)], `${SGp(z)}³ = ${SG(z ** 3)}.`); }
     const y = r() < .5 ? x * x : x * x + r.pick([1, 2, -1]); return C(`Лежит ли точка (${SG(x)}; ${SG(y)}) на графике y = x²?`, y === x * x ? 'да' : 'нет', [y === x * x ? 'нет' : 'да'], `${SGp(x)}² = ${x * x}.`); } }
);
M13_GEOM.push(
 { id:'g7_9', t:'Внешний угол треугольника',
   th:UCH({ pic:'angle|120|180', n:'<b>Внешний угол</b> треугольника — смежный с его внутренним углом.', r:'Внешний угол равен сумме двух внутренних углов, не смежных с ним.', x:'Углы треугольника 50° и 70°. Внешний угол при третьей вершине: 50° + 70° = 120°.', c:'третий угол 60°, а 180° − 60° = 120°.' }),
   g: r => { const a = r.int(3, 9) * 10, b = r.int(2, 8) * 10; if (a + b >= 170) return NV(`Углы треугольника 40° и 60°. Найди внешний угол при третьей вершине.`, 100, [80, 140, 120], '40° + 60° = 100°.');
     return r() < .5 ? NV(`Два угла треугольника ${a}° и ${b}°. Чему равен внешний угол при третьей вершине (в градусах)?`, a + b, [180 - a - b, 180 - a, a + b + 10], `Внешний угол = ${a}° + ${b}° = ${a + b}°.`)
       : NV(`Внешний угол треугольника ${a + b}°, один из не смежных с ним углов ${a}°. Найди другой (в градусах).`, b, [180 - a - b, a, 180 - b], `${a + b}° − ${a}° = ${b}°.`); } },
 { id:'g7_10', t:'Прямоугольный треугольник',
   th:UCH({ pic:'right', n:'Стороны при прямом угле — <b>катеты</b>, против прямого угла — <b>гипотенуза</b> (самая длинная сторона).',
     r:['Сумма острых углов прямоугольного треугольника равна 90°.', 'Катет против угла 30° равен половине гипотенузы.'], x:'Один острый угол 35° — другой 90° − 35° = 55°. Гипотенуза 14 см, угол 30° — катет против него 7 см.' }),
   g: r => { const t = r.int(0, 2), a = r.int(15, 75), h = r.int(3, 15) * 2;
     if (t === 0) return NV(`Один острый угол прямоугольного треугольника ${a}°. Найди другой (в градусах).`, 90 - a, [180 - a, 90 + a, a], `90° − ${a}° = ${90 - a}°.`);
     if (t === 1) return NV(`Гипотенуза ${h} см, один из острых углов 30°. Найди катет против этого угла (в см).`, h / 2, [h, h * 2, h / 2 + 2], 'Катет против 30° — половина гипотенузы.');
     return B(['Какая сторона прямоугольного треугольника самая длинная?|гипотенуза|катет при остром угле;любой катет;все равны','Может ли в треугольнике быть два прямых угла?|нет|да;только в равнобедренном|90° + 90° = 180°, на третий угол ничего не остаётся.','Как называются стороны при прямом угле?|катеты|гипотенузы;медианы;биссектрисы'])(r); } },
 { id:'g7_11', t:'Перпендикуляр и расстояние',
   th:UCH({ pic:'right', n:'<b>Перпендикуляр</b> из точки к прямой — отрезок под прямым углом. Любой другой отрезок из этой точки к прямой — <b>наклонная</b>.',
     r:['Перпендикуляр короче любой наклонной.', 'Расстояние от точки до прямой — длина перпендикуляра.', 'Расстояние между параллельными прямыми одинаково в любом месте.'], x:'Как измерить ширину улицы? По перпендикуляру от одного тротуара к другому, а не наискосок.' }),
   g: B(['Из точки к прямой провели перпендикуляр 5 см и наклонную. Какой может быть наклонная?|7 см|4 см;5 см;3 см|Наклонная длиннее перпендикуляра.','Что считают расстоянием от точки до прямой?|длину перпендикуляра|длину любой наклонной;длину самой длинной наклонной;расстояние до ближайшего угла','Сколько перпендикуляров можно провести из точки к прямой?|один|два;бесконечно много;ни одного','Две прямые перпендикулярны. Какой угол между ними?|90°|180°;45°;60°','Расстояние между двумя параллельными рельсами в начале 1,5 м. Каково оно через километр?|1,5 м|больше 1,5 м;меньше 1,5 м;нельзя сказать|У параллельных прямых расстояние везде одно.','Как прямые a и b, если обе перпендикулярны прямой c?|параллельны|пересекаются;совпадают обязательно;перпендикулярны друг другу']) }
);
