/* Второй трек логики 6 лет — «Внимание и память» (чередуется с логикой по дням) */
const M6_ATT = (function(){
  const F = ['●', '○', '▲', '■'], N = { '●':'чёрных кружков', '○':'белых кружков', '▲':'треугольников', '■':'квадратов' };
  const row = (r, n) => [...Array(n)].map(() => r.pick(F));
  return [
 { id:'v0_1', t:'Сосчитай фигуры', th:UCH({ z:'Сколько треугольников: ▲ ● ▲ ■ ▲', zr:'Ведём пальцем и считаем только ▲: <b>3</b>.', r:'Считай один вид фигур и не отвлекайся на другие.', c:'посчитай второй раз в обратную сторону.' }),
   g: r => { const s = row(r, r.int(6, 10)), f = r.pick([...new Set(s)]), n = s.filter(x => x === f).length; return NV(`Сколько ${N[f]}? ${s.join(' ')}`, n, [n + 1, n - 1 >= 0 ? n - 1 : n + 2, s.length], `Ищем только ${f}: ${n}.`); } },
 { id:'v0_2', t:'Который по счёту не такой?', th:UCH({ z:'▲ ▲ ▲ ■ ▲ — какая фигура не такая?', zr:'Четвёртая: все треугольники, а она — квадрат.', r:'Найди, что повторяется, и отыщи «чужака».', c:'считай слева, начиная с первого.' }),
   g: r => { const a = r.pick(F), b = r.pick(F.filter(x => x !== a)), n = r.int(5, 8), i = r.int(0, n - 1), s = [...Array(n)].map((_, j) => j === i ? b : a); return NV(`Какая по счёту фигура не такая, как все? ${s.join(' ')}`, i + 1, [i + 2, i || n, n].filter(x => x !== i + 1), `Слева: ${i + 1}-я.`); } },
 { id:'v0_3', t:'Чего больше?', th:UCH({ z:'● ○ ● ● ○ — каких кружков больше?', zr:'Чёрных 3, белых 2 — <b>чёрных</b> больше.', r:'Посчитай каждый вид отдельно и сравни.', c:'зачёркивай пары в уме.' }),
   g: r => { let s, a, b; do { s = [...Array(r.int(5, 9))].map(() => r.pick(['●', '○'])); a = s.filter(x => x === '●').length; b = s.length - a; } while (a === b);
     return C(`Каких кружков больше? ${s.join(' ')}`, a > b ? 'чёрных' : 'белых', [a > b ? 'белых' : 'чёрных', 'поровну'], `Чёрных ${a}, белых ${b}.`); } },
 { id:'v0_4', t:'Запомни слова', th:UCH({ r:'Чтобы запомнить слова, представь картинку: кот сидит на стуле и держит яблоко.', x:'Слова: кот, стул, яблоко. Какого слова не было: кот, мяч, стул? — мяча.', c:'повтори слова шёпотом два раза.' }),
   g: r => { const W = ['кот', 'дом', 'мяч', 'лес', 'сыр', 'нос', 'жук', 'сок', 'лук', 'кит', 'шар', 'ёж', 'гриб', 'стол'], s = r.shuffle(W), L = s.slice(0, 3), x = s[3];
     return C(`Запомни: ${L.join(', ')}. Какого слова в списке не было?`, x, L, `В списке были: ${L.join(', ')}.`); } },
 { id:'v0_5', t:'Что изменилось?', th:UCH({ r:'Сравни два ряда по одному месту: первое с первым, второе со вторым.', x:'▲ ● ■ и ▲ ○ ■ — изменилась вторая фигура.', c:'проверь каждое место по порядку.' }),
   g: r => { const n = r.int(3, 5), a = row(r, n), i = r.int(0, n - 1), b = a.slice(); b[i] = r.pick(F.filter(x => x !== a[i])); return NV(`Было: ${a.join(' ')}. Стало: ${b.join(' ')}. Какая по счёту фигура изменилась?`, i + 1, [i + 2, i || n, n + 1].filter(x => x !== i + 1), `Изменилась ${i + 1}-я фигура.`); } },
 { id:'v0_6', t:'Слушай внимательно', th:UCH({ r:'Отвечай только на то, что спрашивают. Лишние слова в задаче — ловушка.', x:'«У Маши жёлтый мяч и синий шарик. Какого цвета мяч?» — жёлтого.', c:'найди в вопросе главное слово.' }),
   g: B(['У Маши жёлтый мяч и синий шарик. Какого цвета мяч?|жёлтого|синего;красного;зелёного', 'Кот спал на диване, а пёс — на коврике. Где спал пёс?|на коврике|на диване;на кровати;в будке', 'Петя съел яблоко, а Оля — грушу. Что съела Оля?|грушу|яблоко;банан;сливу', 'Утром шёл дождь, а вечером светило солнце. Что было утром?|дождь|солнце;снег;ветер',
     'Белый кот и рыжая кошка пили молоко. Какого цвета кошка?|рыжая|белая;чёрная;серая', 'В корзине 3 гриба и 2 ягоды. Сколько грибов?|3|2;5;1', 'Дима играл в мяч, потом рисовал. Что Дима делал сначала?|играл в мяч|рисовал;читал;спал', 'Бабушка испекла пирог, а дедушка налил чай. Кто налил чай?|дедушка|бабушка;мама;папа',
     'Собака лаяла, кошка мяукала, корова мычала. Кто мяукал?|кошка|собака;корова;коза', 'В понедельник шёл снег, во вторник было солнце. Когда шёл снег?|в понедельник|во вторник;в среду;в субботу', 'Красная машина обогнала синюю. Какая машина впереди?|красная|синяя;обе рядом;зелёная', 'Аня взяла зонт, а Катя — шапку. Что взяла Катя?|шапку|зонт;сумку;мяч']) },
 { id:'v0_7', t:'Найди пару', th:UCH({ r:'Ищи две совсем одинаковые группы: те же фигуры в том же порядке.', x:'▲● совпадает с ▲●, а не с ●▲.', c:'сравни первую фигуру, потом вторую.' }),
   g: r => { const a = row(r, 3), o = new Set([a.slice().reverse().join(' ')]); for (let i = 0; i < 3; i++) { const b = a.slice(); b[i] = r.pick(F.filter(x => x !== a[i])); o.add(b.join(' ')); } o.delete(a.join(' '));
     return C(`Найди точно такую же группу: ${a.join(' ')}`, a.join(' '), r.shuffle([...o]), 'Совпадают все фигуры по порядку.'); } },
 { id:'v0_8', t:'Сколько всего?', th:UCH({ r:'Считай всё подряд, ничего не пропуская. Удобно отмечать посчитанное.', x:'●▲■●▲ — пять фигур.', c:'посчитай ещё раз с другого конца.' }),
   g: r => { const s = row(r, r.int(5, 12)); return NV(`Сколько всего фигур? ${s.join(' ')}`, s.length, [s.length - 1, s.length + 1, s.length + 2], `Считаем по одной: ${s.length}.`); } },
 { id:'v0_9', t:'Запомни порядок', th:UCH({ r:'Запоминай не только слова, но и кто за кем: первое, второе, третье.', x:'Слова: мяч, кот, дом. Второе слово — кот.', c:'проговори слова по порядку.' }),
   g: r => { const W = r.shuffle(['кот', 'дом', 'мяч', 'лес', 'сыр', 'нос', 'жук', 'сок', 'лук', 'кит', 'шар', 'ёж']).slice(0, 4), i = r.int(0, 3), O = ['первым', 'вторым', 'третьим', 'четвёртым'];
     return C(`Запомни: ${W.join(', ')}. Какое слово было ${O[i]}?`, W[i], W.filter((_, j) => j !== i), `По порядку: ${W.join(', ')}.`); } },
 { id:'v0_10', t:'Проверка внимания', th:UCH({ r:'Всё вместе: считай, сравнивай, запоминай. Не торопись — внимательность важнее скорости.', c:'перед ответом проверь ещё раз.' }),
   g: null }
  ];
})();
M6_ATT[9].g = MIX(M6_ATT[0].g, M6_ATT[2].g, M6_ATT[4].g, M6_ATT[7].g);
/* 6 лет: ответ-слово выбираем кнопкой, даже если оно есть в условии — печатать слова ещё рано */
[M6_MATH, M6_WORLD, M6_LOGIC, M6_ATT].forEach(L => L.forEach(u => { if (!u.kcw) { const g = u.g; u.g = KC(g); u.kcw = 1; } }));
Object.assign(AGE_CUR[6].logic, { alt: M6_ATT, altName:'Внимание и память' });
AGE_CUR[6].rus.units = Y_READL.slice(0, 20);

